"""'Принципы статистики': 25 short lessons with interactive widgets and check questions -> prindata.json.

Lesson = part, title, lead (one line for the list), html body, optional widget id (drawn by the app),
questions (mc / num / multi, same format as the other sections). Run from tools/: python3 prin_bank.py
"""
import json
import math
import numpy as np


def mc(q, right, wrong, ex, seed):
    rng = np.random.default_rng(seed)
    opts = [right] + list(wrong)
    order = list(rng.permutation(len(opts)))
    return dict(t="mc", q=q, o=[opts[i] for i in order], a=order.index(0), ex=ex)


def num(q, a, ex, tol):
    return dict(t="num", q=q, a=a, tol=tol, ex=ex)


def multi(q, items, ex, seed):
    rng = np.random.default_rng(seed)
    order = list(rng.permutation(len(items)))
    return dict(t="multi", q=q, o=[items[i][0] for i in order], a=sorted(j for j, i in enumerate(order) if items[i][1]), ex=ex)


L = []
S = [100]


def lesson(part, title, lead, html, qs, widget=None):
    L.append(dict(part=part, title=title, lead=lead, html=html, w=widget, qs=qs))


def sd():
    S[0] += 1
    return S[0]


P1, P2, P3, P4, P5 = "Данные и разброс", "Логика вывода", "Планирование опыта", "Модели", "Для работы"

# ============================================================== part 1
lesson(P1, "Единица наблюдения и единица эксперимента", "Кого считать за n — главный вопрос любого анализа",
"""<p>В опыте с рационами взвешивают свиней, а рацион насыпают в кормушку загона. Что здесь «одно наблюдение»?</p>
<ul><li><b>Единица наблюдения</b> — то, что измеряют: свинья, её привес.</li>
<li><b>Единица эксперимента</b> — то, чему жребием назначают вариант. Если рацион дают загону, единица — загон.</li>
<li><b>Единица анализа</b> должна совпадать с единицей эксперимента. Иначе получается <i>псевдоповторность</i>: 12 загонов по 12 свиней превращаются в «144 независимых опыта», и p становится обманчиво маленьким.</li></ul>
<p>Простой тест: спроси себя «что я подбрасывал монеткой?». Это и есть n.</p>
<div class="pr-ex"><b>Примеры.</b> Вакцину колют каждому поросёнку, поросята в общих загонах → единица — поросёнок, но зависимость через заражение остаётся. Опыт с режимом вентиляции в комнатах → единица — комната (а их часто всего 2–4, и это большая проблема). Наблюдение за 30 фермами → единица — ферма, если признак (например, система поения) общий для фермы.</div>
<p>Что делать, если единиц эксперимента мало, а животных много: анализировать средние по единицам или смешанную модель со случайным эффектом единицы, например <code>lmer(adg ~ diet + (1 | pen))</code>.</p>""",
[mc("Подстилку меняли в 4 комнатах (2 с опилками, 2 с соломой), в каждой по 200 свиней. Сколько единиц эксперимента на вариант?",
    "2 комнаты", ["200 свиней", "400 свиней", "4 комнаты"], "Подстилку назначали комнате. На каждый вариант — по 2 комнаты. 400 свиней дают точные средние комнат, но не новые повторности.", sd()),
 mc("Антибиотик кололи отдельным поросятам внутри гнёзд: в каждом гнезде половине. Единица эксперимента?",
    "Поросёнок", ["Гнездо", "Свиноматка", "Ферма"], "Жребий был на уровне поросёнка. Гнездо здесь — блок: оба варианта есть в каждом гнезде.", sd()),
 multi("Что из этого — псевдоповторность?",
       [("Рацион на загон, t-тест по всем свиньям", True), ("Пять взвешиваний одной свиньи как пять независимых наблюдений", True),
        ("Анализ средних загонов, когда рацион назначали загону", False), ("lmer с (1 | pen), когда рацион на загон", False)],
       "Псевдоповторность — когда зависимые измерения считают независимыми. Средние загонов и смешанная модель её убирают.", sd())])

lesson(P1, "Тип отклика подсказывает модель", "Непрерывный, 0/1, счёт, доля — у каждого своя модель",
"""<p>Первое, что смотрят перед анализом, — <b>что за число в столбце отклика</b>.</p>
<table class="pr-t"><tr><th>Отклик</th><th>Пример</th><th>Модель в R</th></tr>
<tr><td>Непрерывный</td><td>привес, толщина шпика</td><td><code>lm</code>, t-тест, ANOVA</td></tr>
<tr><td>0/1 у каждого животного</td><td>пал / не пал</td><td><code>glm(…, family = binomial)</code></td></tr>
<tr><td>Доля из n</td><td>павших из 25 в загоне</td><td><code>glm(cbind(dead, alive) ~ …, family = binomial)</code></td></tr>
<tr><td>Счёт событий</td><td>случаи диареи в загоне</td><td><code>glm(…, family = poisson)</code> + <code>offset(log(свинодни))</code></td></tr>
<tr><td>Время до события</td><td>дни до продажи, до выбраковки</td><td>модели выживаемости (<code>survival</code>)</td></tr>
<tr><td>Порядковый балл</td><td>хромота 0–3</td><td>ранговые тесты, порядковая регрессия</td></tr></table>
<p>Второй вопрос — <b>структура</b>: есть ли группы зависимых наблюдений (загоны, гнёзда, повторные взвешивания)? Если есть — добавляется случайный эффект: <code>lmer</code> вместо <code>lm</code>, <code>glmer</code> вместо <code>glm</code>.</p>
<p>Частая ошибка — посчитать процент павших в загоне и отправить его в <code>lm</code>. Проценты из 5 и из 50 животных одинаково весомы для lm, а разброс у долей зависит от среднего. Биномиальная модель учитывает и то и другое.</p>""",
[mc("Число кашляющих свиней за 10 минут наблюдения в каждой из 40 комнат. Модель?", "Пуассоновская (glm, family = poisson)",
    ["Логистическая", "lm по сырым числам", "t-тест"], "Счёт событий за одинаковое время — Пуассон. Если время наблюдения разное — offset(log(время)).", sd()),
 mc("Доля павших в каждом из 30 загонов, в загонах от 18 до 32 поросят. Модель?", "glm(cbind(dead, n - dead) ~ …, family = binomial)",
    ["lm(pct_dead ~ …)", "glm(pct_dead ~ …, family = poisson)", "chisq.test по процентам"], "cbind(успехи, неудачи) учитывает, из скольких животных посчитана каждая доля.", sd()),
 mc("FCR (корм / привес) по загонам. Самая разумная первая модель?", "lm (или lmer, если загоны в блоках), но проверить остатки: отношения бывают асимметричны",
    ["Логистическая", "Пуассоновская", "Ранговый тест обязательно"], "FCR — непрерывное число. Часто работает lm; при асимметрии помогает log(FCR).", sd())])

lesson(P1, "SD и SE: разброс животных и точность среднего", "SD описывает свиней, SE — насколько точно мы знаем среднее",
"""<p><b>SD</b> (стандартное отклонение) — как сильно отличаются животные друг от друга. Привес 800 ± 60 г/сут: типичная свинья отклоняется от среднего на ~60 г.</p>
<p><b>SE</b> (стандартная ошибка среднего) — как сильно отличалось бы <i>среднее</i>, если повторить опыт с другими свиньями. SE = SD / √n. При n = 36 SE = 60 / 6 = 10 г/сут.</p>
<p>SD не уменьшается с ростом n — свиньи не становятся одинаковее. SE уменьшается: среднее по 100 свиньям точнее, чем по 10. Чтобы SE уменьшилась вдвое, нужно в 4 раза больше животных.</p>
<p>Попробуй ниже: возьми много выборок из асимметричной совокупности (массы при рождении) и посмотри на распределение их средних. При n от 30 оно почти нормальное, даже если сами массы не нормальные, — это центральная предельная теорема. Поэтому t-тест устойчив к умеренной ненормальности при больших n.</p>""",
[num("SD привеса 60 г/сут, n = 25 свиней. Чему равна SE среднего?", 12, "SE = 60 / √25 = 60 / 5 = <b>12</b> г/сут.", 0.01),
 mc("В статье: «привес 812 ± 9 г/сут (n = 40)». Скорее всего это…", "SE: SD при n = 40 было бы около 57",
    ["SD: свиньи почти одинаковые", "Размах", "Доверительный интервал"], "Разброс привеса свиней обычно 50–80 г/сут. ± 9 при n = 40 — это SE (9 × √40 ≈ 57). Всегда пиши, что стоит после ±.", sd()),
 mc("Во сколько раз нужно увеличить n, чтобы SE уменьшилась в 3 раза?", "В 9 раз", ["В 3 раза", "В 6 раз", "В √3 раз"], "SE ∝ 1/√n: втрое меньше SE → в 3² = 9 раз больше n.", sd())],
widget="sampling")

lesson(P1, "Выборка и совокупность", "На кого можно перенести вывод",
"""<p>Статистика отвечает про <b>совокупность</b>, из которой взята выборка. Если опыт шёл на одной ферме с одной генетикой, вывод строго — про свиней этой фермы в этих условиях. Перенос на другие фермы — уже суждение специалиста, а не статистика.</p>
<p><b>Случайный отбор</b> делает выборку похожей на совокупность. Его заменители почти всегда вносят смещение:</p>
<ul><li>«Взяли первых 20 поросят, кого поймали» — поймали медленных и слабых.</li>
<li>«Данные бойни» — только доживших до убоя; павшие и выбракованные выпали (смещение выживших).</li>
<li>«Опросили фермы, которые ответили» — ответили самые организованные.</li></ul>
<p><b>Рандомизация</b> в опыте и <b>случайный отбор</b> — разные вещи. Жребий между вариантами даёт право на вывод о <i>причине</i>. Случайный отбор из совокупности даёт право на <i>обобщение</i>. Хороший опыт на одной ферме — сильная причинность, слабое обобщение.</p>""",
[mc("Пневмонию оценивали по лёгким на бойне. На кого переносится доля поражённых лёгких?", "На свиней, доживших до убоя; павшие от пневмонии в выборку не попали",
    ["На всех свиней фермы", "На всех свиней страны", "Ни на кого: бойня — не опыт"], "Классическое смещение выживших: самые тяжёлые случаи пали раньше.", sd()),
 mc("Опыт с жребием на одной ферме показал эффект. Что можно утверждать?", "Добавка вызывает эффект у таких свиней в таких условиях",
    ["Добавка работает везде", "Это только корреляция", "Нельзя ничего"], "Жребий → причинность; одна ферма → обобщение ограничено.", sd())])

# ============================================================== part 2
lesson(P2, "Доверительный интервал", "Что на самом деле значит «95%»",
"""<p>95% доверительный интервал — это интервал, построенный методом, который в 95% повторений опыта накрывает истинное значение. Про один конкретный интервал говорят: «правдоподобные значения параметра».</p>
<p>Чего ДИ <b>не</b> значит:</p><ul><li>что 95% животных попадают в интервал — для отдельных животных есть интервал прогноза, он намного шире;</li>
<li>что истинное значение лежит в нём с вероятностью 95% (строго говоря, оно либо там, либо нет).</li></ul>
<p>Практическое чтение: <b>ширина</b> = точность, <b>положение</b> = размер эффекта. ДИ разницы (12; 84) г/сут говорит: эффект положительный, но может быть и маленьким, и большим. ДИ (−40; 70) — данных мало, вывода нет.</p>
<p>Ниже — 50 повторений одного опыта. Каждый отрезок — ДИ из своей выборки. Красные не накрыли истинное среднее. Поменяй n и уровень доверия: ширина и доля промахов меняются по-разному.</p>""",
[mc("ДИ разницы привеса: от −5 до 61 г/сут. Что верно?", "Данные согласуются и с отсутствием эффекта, и с большим эффектом — нужно больше данных",
    ["Эффекта нет", "Эффект точно 28 г/сут", "95% свиней выросли на −5…61"], "0 внутри → p &gt; 0,05, но верхняя граница большая. Это «не знаем», а не «нет».", sd()),
 mc("Как изменится ширина 95% ДИ, если n вырастет в 4 раза?", "Уменьшится примерно вдвое", ["Уменьшится в 4 раза", "Не изменится", "Вырастет"], "Ширина ∝ SE ∝ 1/√n.", sd()),
 mc("99% ДИ по сравнению с 95% по тем же данным…", "Шире", ["Уже", "Такой же", "Сдвинут вправо"], "Чтобы чаще накрывать истину, интервал должен быть шире.", sd())],
widget="ci")

lesson(P2, "p-value", "Что это, чего это не значит и почему 0,05 — не магия",
"""<p><b>p-value</b> — вероятность получить такую же или ещё более сильную разницу, <i>если бы</i> на самом деле эффекта не было (нулевая гипотеза верна).</p>
<p>Маленькое p — данные плохо согласуются с «эффекта нет». Большое p — данные с этим согласуются (но и с умеренным эффектом тоже).</p>
<p>Частые неверные прочтения:</p><ul><li>«p = 0,03 — вероятность, что эффекта нет, 3%». Нет: p считают, <i>предположив</i>, что эффекта нет.</li>
<li>«p = 0,2 — эффекта нет». Нет: может, данных просто мало.</li>
<li>«p = 0,001 — эффект большой». Нет: при огромном n даже 3 г/сут дадут крошечное p.</li></ul>
<p>Симуляция ниже: 1000 опытов. Когда эффекта нет, p распределены равномерно — 5% из них случайно меньше 0,05. Когда эффект есть, p сжимаются к нулю, и доля p &lt; 0,05 — это <b>мощность</b>.</p>""",
[mc("Эффекта нет, сделали 1000 одинаковых опытов. Сколько из них дадут p &lt; 0,05?", "Около 50", ["0", "Около 500", "Около 950"], "Под H₀ p равномерно на (0; 1): 5% случайно меньше 0,05 — это ложные тревоги.", sd()),
 mc("Опыт на 5000 свиней: разница 3 г/сут, p = 0,0004. Вывод?", "Разница почти наверняка не нулевая, но 3 г/сут вряд ли имеет экономический смысл",
    ["Очень сильный эффект", "Ошибка в анализе", "Добавку надо внедрять"], "p отвечает «есть ли», а не «сколько». Смотри на оценку и ДИ.", sd()),
 multi("Отметь верные утверждения о p = 0,04.",
       [("Если бы эффекта не было, такая разница встречалась бы примерно в 4% опытов", True), ("Вероятность нулевой гипотезы — 4%", False),
        ("Эффект скорее всего большой", False), ("Результат был бы «не значимым» при α = 0,01", True)],
       "p — свойство данных при допущении H₀, а не вероятность гипотезы.", sd())],
widget="pval")

lesson(P2, "Ошибки I и II рода, мощность", "Почему «не значимо» часто значит «мало животных»",
"""<table class="pr-t"><tr><th></th><th>Эффекта нет</th><th>Эффект есть</th></tr>
<tr><td>Нашли «эффект» (p &lt; α)</td><td>Ошибка I рода (α, обычно 5%)</td><td>Верно: это мощность</td></tr>
<tr><td>Не нашли</td><td>Верно</td><td>Ошибка II рода (β)</td></tr></table>
<p><b>Мощность</b> = 1 − β — шанс заметить эффект заданного размера. Принято планировать 80%. Мощность растёт, когда: эффект больше, разброс меньше (блоки, точные измерения), n больше, α больше.</p>
<p>Опыт с мощностью 30% — почти бесполезен: эффект чаще всего «не найдётся», а если найдётся, его размер будет преувеличен (повезло получить большую разницу).</p>
<p>Для двух групп в R: <code>power.t.test(delta = 25, sd = 40, power = 0.8)</code> — сколько единиц на группу. Калькулятор ниже использует нормальное приближение — R даст на 1–2 единицы больше.</p>""",
[mc("Опыт: 6 загонов на рацион, p = 0,31. Что сказать фермеру?", "Опыт не может ни подтвердить, ни опровергнуть эффект — загонов слишком мало",
    ["Рацион не работает", "Рацион работает на 69%", "Нужно повторить с α = 0,5"], "При малой мощности «не значимо» почти ничего не значит. Смотри на ДИ.", sd()),
 mc("Что увеличит мощность, не добавляя загонов?", "Блоки по комнатам, если комнаты различаются", ["Уменьшить α до 0,01", "Взвешивать реже", "Убрать контроль"],
    "Блоки убирают известный разброс из ошибки → меньше SD → больше мощность.", sd()),
 num("SD 40, разница 25, α = 0,05, мощность 80%. Примерно сколько единиц на группу? (формула 2·(1,96 + 0,84)²·SD²/Δ²)", 40.1,
     "2 × 2,8² × 1600 / 625 = 2 × 7,84 × 2,56 ≈ <b>40</b>. power.t.test даст ≈ 41.", 2.5)],
widget="power")

lesson(P2, "Значимо ≠ важно", "Размер эффекта, ДИ и порог пользы",
"""<p>Статистическая значимость отвечает на вопрос «отличается ли от нуля». Практике нужно другое: <b>больше ли эффект, чем порог пользы</b>.</p>
<p>Пример. Добавка стоит денег; она окупается, если привес выше хотя бы на 20 г/сут. Четыре опыта:</p>
<table class="pr-t"><tr><th>ДИ разницы</th><th>Значимо?</th><th>Что делать</th></tr>
<tr><td>(25; 60)</td><td>да</td><td>окупается: весь ДИ выше порога</td></tr>
<tr><td>(4; 38)</td><td>да</td><td>эффект есть, окупаемость не доказана</td></tr>
<tr><td>(−6; 50)</td><td>нет</td><td>данных мало</td></tr>
<tr><td>(−4; 9)</td><td>нет</td><td>практически бесполезно: даже верхняя граница ниже порога</td></tr></table>
<p>Последняя строка — <b>доказанное отсутствие важного эффекта</b>. Для этого нужен узкий ДИ, а не просто p &gt; 0,05.</p>
<p>Ещё одна ловушка — относительные эффекты. «Падёж снизился на 50%» звучит сильно, но если с 2% до 1% — это минус 1 поросёнок из 100. Пиши обе величины: относительную и абсолютную.</p>""",
[mc("Порог пользы 20 г/сут. ДИ разницы (8; 31). Что верно?", "Эффект есть, но может быть ниже порога — окупаемость не доказана",
    ["Добавка окупается", "Эффекта нет", "Нужно смотреть только на p"], "Нижняя граница 8 &lt; 20.", sd()),
 num("Падёж снизился с 4% до 3%. Сколько поросят спасено на 1000?", 10, "4% − 3% = 1 п.п. = <b>10</b> из 1000. Относительно — снижение на 25%.", 0.1)])

lesson(P2, "Множественные сравнения", "20 тестов — одна ложная находка почти гарантирована",
"""<p>Каждый тест при α = 0,05 — 5% риска ложной тревоги. Если делать много тестов, риск хотя бы одной ошибки растёт: 1 − 0,95<sup>k</sup>. При 3 тестах — 14%, при 20 — 64%.</p>
<p>Где это случается в работе:</p><ul><li>сравнили 5 рационов попарно (10 пар) обычными t-тестами;</li>
<li>смотрели 15 показателей (привес, FCR, падёж, …) и написали только о значимом;</li>
<li>разбили по полу, сезону, ферме и нашли эффект «у свинок зимой» (подгруппы).</li></ul>
<p>Что делать: заранее назвать <b>главный</b> показатель и сравнения; для пар — Tukey или <code>emmeans</code> с поправкой; подгруппы — только как гипотезы для нового опыта. Бонферрони: делить α на число тестов (грубо, но просто).</p>""",
[num("Сколько процентов риска хотя бы одной ложной тревоги при 10 независимых тестах (α = 0,05)?", 40.1, "1 − 0,95¹⁰ = 1 − 0,599 = <b>40</b>%.", 1.0),
 mc("В отчёте: «эффект добавки значим только у свинок 2-го опороса зимой (p = 0,04)». Что думать?", "Скорее всего случайная находка в подгруппе — проверять отдельным опытом",
    ["Добавку давать только этим свинкам", "Эффект доказан", "Поправка не нужна, раз p &lt; 0,05"], "Чем больше подгрупп смотрели, тем вероятнее случайная «находка».", sd()),
 num("Поправка Бонферрони: 5 тестов, общий α = 0,05. Какой порог для каждого?", 0.01, "0,05 / 5 = <b>0,01</b>.", 0.0005)],
widget="multi")

# ============================================================== part 3
lesson(P3, "Рандомизация, контроль, слепота", "Три вещи, которые делают опыт честным",
"""<p><b>Рандомизация</b> — вариант назначает жребий (<code>sample()</code> в R), а не человек. Тогда тяжёлые/лёгкие, здоровые/больные распределяются между группами случайно, и разница групп — эффект варианта плюс шум, которой статистика умеет оценить. «Выбрал загоны, где поросята покрепче» — смещение, которое никакой анализ не уберёт.</p>
<p><b>Одновременный контроль</b> — группа без воздействия в то же время и в тех же условиях. «Исторический контроль» (прошлый месяц) смешивает эффект с сезоном, партией, здоровьем стада.</p>
<p><b>Слепота</b> — тот, кто оценивает (хромоту, диарею, балл кондиции), не знает вариант. Иначе ожидания влияют на оценку.</p>
<p>Как сделать жребий в R:</p>
<pre class="pr-code">set.seed(2026)                                    # жребий можно будет повторить
pens <- data.frame(pen = 1:24, room = rep(1:6, each = 4))
pens$diet <- sample(rep(c("A", "B", "C", "D"), each = 6))   # без блоков: по 6 загонов
# с блоками: в каждой комнате 4 загона получают A, B, C, D в случайном порядке
pens$diet <- unlist(lapply(split(pens$pen, pens$room),
                           function(i) sample(c("A", "B", "C", "D"))))</pre>""",
[mc("Ветеринар выбрал для новой схемы лечения «самых тяжёлых» свиней. Что не так?", "Нет жребия: группы различались до лечения, эффект схемы смешан с тяжестью",
    ["Всё правильно — лечить надо тяжёлых", "Мало животных", "Нужен t-тест Уэлча"], "Без рандомизации разницу нельзя приписать схеме.", sd()),
 mc("Сравнили падёж этого месяца (новая вакцина) с прошлым месяцем. Главная проблема?", "Исторический контроль: месяцы различаются не только вакциной",
    ["Слишком мало дней", "Нужна логистическая регрессия", "Проблем нет"], "Сезон, партия поросят, давление инфекции — всё смешано с вакциной.", sd()),
 mc("Зачем <code>set.seed()</code> перед <code>sample()</code>?", "Чтобы жребий можно было воспроизвести и проверить", ["Чтобы жребий был честнее", "Чтобы группы получились одинаковыми по массе", "R без этого не работает"],
    "Seed фиксирует генератор: тот же код даст то же распределение. Это нужно для протокола и аудита.", sd())])

lesson(P3, "Псевдоповторность и design effect", "Сколько «независимых свиней» в загоне на самом деле",
"""<p>Свиньи одного загона похожи: общая кормушка, микроклимат, болезни. Насколько — измеряет <b>ICC</b> (внутриклассовая корреляция): доля разброса, которая приходится на различия между загонами. ICC = τ² / (τ² + σ²) из <code>lmer</code>.</p>
<p><b>Design effect</b> DE = 1 + (m − 1) × ICC, где m — животных в загоне. Он показывает, во сколько раз зависимость уменьшает информацию. Эффективное n = всего животных / DE.</p>
<p>При ICC = 0,1 и 25 свиньях в загоне: DE = 1 + 24 × 0,1 = 3,4. 300 свиней «стоят» как 88 независимых. Для вариантов, назначенных загону, ещё строже: информация о рационе — от числа загонов.</p>
<p>Отсюда правило планирования: больше загонов лучше, чем больше свиней в загоне. Поиграй с калькулятором.</p>""",
[num("ICC = 0,2, 11 свиней в загоне. DE?", 3.0, "1 + 10 × 0,2 = <b>3</b>.", 0.01),
 num("200 свиней, DE = 4. Эффективное n?", 50, "200 / 4 = <b>50</b>.", 0.5),
 mc("Что выгоднее для точности при той же цене: 20 загонов по 10 свиней или 10 загонов по 20?", "20 загонов по 10", ["10 загонов по 20", "Одинаково", "Зависит только от числа свиней"],
    "Когда вариант на загон, число загонов решает почти всё.", sd())],
widget="deff")

lesson(P3, "Блоки и пары", "Убрать из ошибки то, что известно заранее",
"""<p>Если заранее известно, что единицы различаются (комнаты, ряды загонов, гнёзда, недели заселения), их группируют в <b>блоки</b> и внутри каждого блока разыгрывают все варианты. Тогда различия блоков не попадают в ошибку.</p>
<ul><li><b>RCBD</b>: в каждой комнате все рационы по одному загону. <code>aov(adg ~ factor(room) + diet)</code> или <code>lmer(adg ~ diet + (1 | room))</code>.</li>
<li><b>Пары</b> — блок из двух: два поросёнка одного гнезда и пола, один на вариант A, другой на B → парный t-тест.</li>
<li><b>Латинский квадрат</b> — два источника разброса сразу (комнаты и периоды).</li></ul>
<p>Блок выбирают <b>до</b> опыта по тому, что заметно влияет на отклик. Блок, который ничего не делает, стоит несколько df ошибки — небольшая плата. Блок, забытый в анализе, превращает хороший опыт в слабый.</p>""",
[mc("Опыт в 4 комнатах, в каждой все 3 рациона. Анализ забыл комнату. Что произойдёт?", "Разница комнат уйдёт в ошибку, тест станет слабее",
    ["Ничего", "Тест станет слишком смелым", "R выдаст ошибку"], "MSE вырастет на вклад комнат, F упадёт.", sd()),
 mc("Что лучше сделать блоком в опыте на поросятах-сосунах?", "Гнездо: поросята одного гнезда похожи", ["Пол поросёнка", "Номер ушной бирки", "Вариант лечения"],
    "Гнездо — мать, молоко, место. Разыгрывая варианты внутри гнезда, убирают эти различия.", sd())])

lesson(P3, "Конфаундер, медиатор, коллайдер", "Что добавлять в модель, а что нельзя",
"""<p>В наблюдательных данных (нет жребия) связь X и Y может быть ложной. Нарисуй стрелки «что на что влияет» и посмотри на третью переменную Z:</p>
<ul><li><b>Конфаундер</b> (вмешивающийся): Z влияет и на X, и на Y. Крупные фермы чаще вакцинируют (Z → X) и сами по себе имеют другой падёж (Z → Y). <b>Поправлять надо</b>: добавить Z в модель.</li>
<li><b>Медиатор</b>: X → Z → Y. Добавка повышает потребление корма, а оно — привес. Если поправить на потребление, «съешь» тот самый путь, которым добавка работает. <b>Для общего эффекта не поправлять.</b></li>
<li><b>Коллайдер</b>: X → Z ← Y. Данные только по свиньям, отправленным на лечение (Z), куда попадают и из-за X, и из-за Y. Отбор по Z создаёт ложную связь X и Y. <b>Не поправлять и не отбирать по Z.</b></li></ul>
<p>Добавлять в модель «всё, что есть» — плохая стратегия: медиаторы и коллайдеры искажают оценку. Решение принимают по смыслу, до анализа.</p>""",
[mc("Связь «система поения → падёж» на 40 фермах. Размер фермы влияет на выбор системы и на падёж. Размер фермы — это…", "Конфаундер: добавить в модель",
    ["Медиатор: не добавлять", "Коллайдер: не добавлять", "Не важен"], "Влияет на обе переменные — классический конфаундер.", sd()),
 mc("Опыт с ферментом (жребий). Модель adg ~ enzyme + intake, где intake — потребление корма. Что не так?", "Потребление — медиатор: поправка убирает часть эффекта фермента",
    ["Ничего, больше переменных — лучше", "Нужен glm", "Intake — конфаундер"], "Если фермент работает через аппетит, поправка на аппетит спрячет эффект.", sd()),
 mc("Изучали только свиней, попавших в лазарет. Там оказалось, что тяжёлые реже болеют диареей. Возможное объяснение?", "Отбор по коллайдеру: в лазарет попадают и по массе, и по диарее",
    ["Масса защищает от диареи", "Мало данных", "Конфаундер — пол"], "Отбор по общему следствию двух причин рождает ложную связь между ними.", sd())])

lesson(P3, "Когорта, случай-контроль, срез: RR и OR", "Какая мера эффекта законна в каком исследовании",
"""<table class="pr-t"><tr><th>Дизайн</th><th>Как набирают</th><th>Мера</th></tr>
<tr><td>Опыт / когорта</td><td>по воздействию (вакцинированные / нет), следят за исходом</td><td>риск, RR, разница рисков, OR</td></tr>
<tr><td>Случай-контроль</td><td>по исходу (больные фермы / здоровые), смотрят воздействие в прошлом</td><td>только OR</td></tr>
<tr><td>Срез</td><td>один момент, всё сразу</td><td>распространённость, OR или PR; причинность слабая — неясно, что было раньше</td></tr></table>
<p><b>RR</b> (относительный риск) = риск в группе / риск в контроле. <b>OR</b> (отношение шансов) = шансы / шансы, где шансы = p / (1 − p). При редком исходе (&lt; 10%) OR ≈ RR. При частом OR сильнее отходит от 1.</p>
<p>Почему в случай-контроль нет RR: исследователь сам решил, сколько больных и здоровых взять. «Доля больных среди вакцинированных» в таких данных искусственная.</p>
<p>В ветеринарии: эффективность вакцины VE = (1 − RR) × 100%.</p>""",
[num("Риск пневмонии: 30% у невакцинированных, 12% у вакцинированных. VE, %?", 60, "RR = 0,12 / 0,30 = 0,4; VE = (1 − 0,4) × 100 = <b>60</b>%.", 0.5),
 num("Риск 30% и 12%. OR (вакц. / невакц.)?", 0.318, "Шансы: 0,12/0,88 = 0,136 и 0,30/0,70 = 0,429. OR = 0,136 / 0,429 = <b>0,32</b>. RR = 0,4 — при частом исходе OR дальше от 1.", 0.01),
 mc("Сравнили 30 ферм с PRRS-вспышкой и 60 без неё по закупке ремонтных свинок со стороны. Какая мера?", "OR: это случай-контроль",
    ["RR", "Разница рисков", "VE"], "Набор по исходу (вспышка) — только OR.", sd())])

# ============================================================== part 4
lesson(P4, "Всё есть lm: t-тест, ANOVA и регрессия", "Модель = среднее + шум",
"""<p>Почти все классические тесты — частные случаи одной модели: отклик = среднее, зависящее от X, + случайный шум.</p>
<ul><li>t-тест (pooled) = <code>lm(adg ~ diet)</code> с двумя уровнями: коэффициент — разница средних, t тот же.</li>
<li>Однофакторный ANOVA = <code>lm(adg ~ diet)</code> с 3+ уровнями; F в <code>anova(m)</code> = F в <code>summary(aov())</code>.</li>
<li>Простая регрессия = <code>lm(adg ~ start_wt)</code>; ANCOVA = <code>lm(adg ~ diet + start_wt)</code>.</li></ul>
<p>Как R кодирует фактор: первый уровень — базовый, он «сидит» в <code>(Intercept)</code>, остальные коэффициенты — разницы с ним. <code>dietB = 25</code> значит «B на 25 выше A».</p>
<p>Отсюда одинаковые предпосылки для всего семейства: независимость, равные дисперсии, примерно нормальные остатки, правильная форма связи. И одинаковая диагностика: <code>plot(m)</code>.</p>""",
[mc("<code>lm(adg ~ diet)</code>, уровни A, B, C. Коэффициенты: (Intercept) 790, dietB 25, dietC −10. Среднее C?", "780", ["−10", "790", "805"], "C = 790 + (−10) = 780.", sd()),
 mc("Чем t-тест Уэлча отличается от <code>lm(adg ~ diet)</code>?", "Уэлч не требует равных дисперсий; lm — как pooled t-тест", ["Ничем", "lm не умеет две группы", "Уэлч — непараметрический"],
    "lm оценивает одну общую σ.", sd())])

lesson(P4, "Взаимодействие", "Когда эффект одного фактора зависит от другого",
"""<p>Взаимодействие — «разница разниц». Высокоэнергетический рацион добавляет боровам +60 г/сут, а свинкам +5. Говорить «эффект энергии» без уточнения пола — вводить в заблуждение.</p>
<p>В R: <code>lm(adg ~ energy * sex)</code> = главные эффекты + <code>energy:sex</code>. Порядок чтения:</p>
<ol><li>Сначала строка взаимодействия в <code>anova(m)</code>.</li><li>Если значимо — эффекты одного фактора отдельно на каждом уровне другого: <code>pairs(emmeans(m, ~ energy | sex))</code>.</li>
<li>Если нет — можно читать главные эффекты (или упростить модель до <code>energy + sex</code>).</li></ol>
<p>Ловушка: в модели с взаимодействием коэффициент <code>energyhigh</code> — эффект энергии <b>у базового пола</b>, а не «в среднем».</p>
<p>На графике взаимодействия (<code>interaction.plot</code>) параллельные линии = нет взаимодействия, расходятся или пересекаются = есть.</p>""",
[mc("Средние: low/barrow 810, high/barrow 870, low/gilt 830, high/gilt 835. Взаимодействие (разница разниц)?", "55 г/сут", ["60", "5", "0"],
    "(870 − 810) − (835 − 830) = 60 − 5 = 55.", sd()),
 mc("В модели adg ~ energy * sex коэффициент energyhigh = 60 (база sex = barrow). Это…", "Эффект энергии у боровов", ["Средний эффект по полам", "Эффект у свинок", "Взаимодействие"],
    "При взаимодействии главный коэффициент — эффект при базовом уровне другого фактора.", sd())])

lesson(P4, "Поправка на ковариату и парадокс Симпсона", "Почему сырые сравнения обманывают",
"""<p>Сравниваем две фермы по падежу: на ферме A 6%, на B 4%. Но на A больше поросят от первоопоросок, у которых падёж выше везде. По каждой категории отдельно A лучше B. Это <b>парадокс Симпсона</b>: состав групп разный, и сырое сравнение переворачивает вывод.</p>
<table class="pr-t"><tr><th></th><th>Ферма A</th><th>Ферма B</th></tr>
<tr><td>Помёты свинок</td><td>60/800 = 7,5%</td><td>20/200 = 10%</td></tr>
<tr><td>Помёты свиноматок</td><td>12/400 = 3%</td><td>32/800 = 4%</td></tr>
<tr><td>Всего</td><td>72/1200 = 6%</td><td>52/1000 = 5,2%</td></tr></table>
<p>Решение — сравнивать «при прочих равных»: добавить ковариату в модель (<code>glm(dead ~ farm + parity, family = binomial)</code>) или сравнивать внутри слоёв.</p>
<p>В опыте с жребием ковариата (начальная масса) не нужна для честности, но <b>уменьшает ошибку</b>: часть разброса привеса объясняется массой при постановке. Это ANCOVA: <code>lm(adg ~ diet + start_wt)</code>.</p>""",
[mc("По таблице: какая ферма лучше по падежу?", "A: она лучше и у свинок, и у свиноматок; сырой итог искажён составом", ["B: у неё 5,2% против 6%", "Одинаковы", "Нельзя сказать"],
    "Внутри каждой категории A лучше. У A больше помётов свинок, где падёж выше.", sd()),
 mc("Зачем в опыте с жребием добавлять начальную массу в модель?", "Уменьшить остаточную ошибку и повысить мощность", ["Чтобы убрать смещение", "Это обязательное требование R", "Чтобы поменять оценку эффекта"],
    "Жребий уже защищает от смещения. Ковариата делает оценку точнее.", sd())])

lesson(P4, "Логарифмы и exp(β): эффекты в разах", "Как читать log(Y), логистическую и пуассоновскую",
"""<p>Когда разброс растёт вместе со средним или эффекты естественно мультипликативные (титры, бактерии, концентрации), берут логарифм. Коэффициенты тогда читаются в разах:</p>
<table class="pr-t"><tr><th>Модель</th><th>exp(β) — это</th><th>Пример</th></tr>
<tr><td><code>lm(log(y) ~ x)</code></td><td>во сколько раз меняется медиана Y на +1 X</td><td>exp(−0,16) = 0,85: титр падает на 15% в неделю</td></tr>
<tr><td><code>glm(…, binomial)</code></td><td>отношение шансов (OR)</td><td>exp(−0,35) = 0,70 на +100 г</td></tr>
<tr><td><code>glm(…, poisson)</code></td><td>отношение частот (IRR)</td><td>exp(−0,4) = 0,67: на 33% меньше случаев</td></tr></table>
<p>Для маленьких β: exp(β) − 1 ≈ β. β = 0,05 ≈ +5%; β = 0,5 — уже +65%, приближение не работает.</p>
<p>Если логарифм у X: <code>lm(y ~ log(x))</code> — удвоение X меняет Y на β × log(2) = 0,69β.</p>""",
[num("lm(log(titre) ~ week): β = −0,22. На сколько процентов падает титр за неделю?", 19.7, "exp(−0,22) = 0,80 → падение на <b>20</b>%.", 0.6),
 num("Пуассон: β = 0,693. Во сколько раз больше частота?", 2.0, "exp(0,693) = <b>2</b>.", 0.02),
 num("lm(y ~ log(x)): β = 10. Насколько меняется Y при удвоении X?", 6.93, "10 × ln 2 = <b>6,93</b>.", 0.05)])

lesson(P4, "Смешанные модели: зачем случайные эффекты", "Фиксированные и случайные эффекты, сжатие к среднему",
"""<p><b>Фиксированный эффект</b> — то, что нас интересует само по себе и повторится в другом опыте: рацион, доза, пол. <b>Случайный</b> — источник группировки, конкретные уровни которого не важны: какие именно загоны, гнёзда, фермы. Важен их разброс (τ²).</p>
<p>Что даёт <code>(1 | pen)</code>:</p><ul><li>правильные SE и df для эффектов, назначенных загонам;</li>
<li>ICC — какая доля разброса между группами;</li><li>оценки загонов (BLUP), <b>сжатые к общему среднему</b>: загон из 3 свиней с привесом 950 модель «подвинет» к среднему сильнее, чем загон из 30 — данных меньше, доверия меньше.</li></ul>
<p>Когда делать группу случайной: уровней 5 и больше, и они — выборка из множества (загоны, фермы). Когда фиксированной: уровней мало, они интересны сами (3 комнаты вашей фермы) или их меньше 5.</p>
<p>Вложенность: свиньи в загонах в комнатах → <code>(1 | room/pen)</code>. Повторные измерения → <code>(1 | pig)</code>, при разной скорости роста — <code>(week | pig)</code>.</p>""",
[mc("Опыт на 20 фермах, на каждой оба рациона. Ферма — это…", "Случайный эффект: фермы — выборка, важен их разброс", ["Фиксированный эффект", "Не нужна в модели", "Отклик"],
    "20 ферм — выборка из всех ферм; хотим обобщить на другие.", sd()),
 mc("BLUP загона из 3 свиней сдвинут к общему среднему сильнее, чем загона из 30. Почему?", "По 3 свиньям среднее ненадёжно: модель меньше ему доверяет",
    ["Ошибка модели", "Маленькие загоны хуже растут", "Так задумано для красоты"], "Сжатие пропорционально надёжности: τ² / (τ² + σ²/m).", sd())])

lesson(P4, "Выбор модели: AIC и переобучение", "Простая модель часто лучше сложной",
"""<p>Добавляя предикторы, всегда улучшаешь подгонку (R² растёт). Но модель начинает описывать шум конкретной выборки — <b>переобучение</b>: на новых данных она хуже.</p>
<p><b>AIC</b> = −2·logLik + 2k: подгонка минус штраф за число параметров k. Меньше — лучше; разница &lt; 2 — модели равноценны, &gt; 10 — сильное преимущество. AIC сравнивают только для моделей на <b>одних и тех же</b> данных и одном отклике (нельзя сравнить y и log(y)).</p>
<p>Правила для работы:</p><ul><li>Сначала цель. Для проверки эффекта опыта модель задаётся дизайном (рацион + блок), а не отбором.</li>
<li>Для прогноза — сравнивай по AIC или по ошибке на отложенных данных.</li>
<li>Не перебирай все комбинации (<code>dredge</code>) без цели — это множественные сравнения под другим именем.</li>
<li>Правило 10–15: на каждый оцениваемый коэффициент хотя бы 10–15 наблюдений (для логистической — 10 событий).</li></ul>""",
[mc("Модель 1: AIC = 512,4. Модель 2 (+2 параметра): AIC = 511,8. Что выбрать?", "Разница &lt; 2 — модели равноценны, лучше простая", ["Модель 2: AIC меньше", "Модель 1: в ней меньше параметров — всегда лучше", "Сравнить R²"],
    "0,6 единицы AIC — не повод усложнять.", sd()),
 mc("Логистическая регрессия: 40 павших из 600. Сколько коэффициентов разумно оценивать?", "Около 4", ["60", "40", "600"], "Правило 10 событий на параметр: 40 / 10 = 4.", sd())])

# ============================================================== part 5
lesson(P5, "Диагностические тесты: Se, Sp, PPV, NPV", "Почему положительный ELISA в здоровом стаде часто ложный",
"""<p><b>Чувствительность (Se)</b> — доля положительных среди больных. <b>Специфичность (Sp)</b> — доля отрицательных среди здоровых. Это свойства теста.</p>
<p>Для решения на ферме нужно другое: <b>PPV</b> — вероятность, что положительное животное действительно больно; <b>NPV</b> — что отрицательное здорово. Они зависят от <b>распространённости</b>.</p>
<p>Пример: ELISA Se = 95%, Sp = 98%. В стаде, где больных 1%, из 1000 свиней: 10 больных → 9,5 положительных; 990 здоровых → 19,8 ложно положительных. PPV = 9,5 / 29,3 = 32%: две трети положительных — ложные. В стаде с 30% больных PPV = 95%.</p>
<p>Практика: в свободном от болезни стаде одиночный положительный результат подтверждают другим тестом (ПЦР) или повторной выборкой. Отрицательный результат при низкой распространённости надёжен (NPV ≈ 100%).</p>""",
[num("Se = 90%, Sp = 95%, распространённость 10%. PPV, %?", 66.7, "1000 животных: больных 100 → 90 TP; здоровых 900 → 45 FP. PPV = 90 / 135 = <b>66,7</b>%.", 0.6),
 mc("Тест тот же, распространённость упала до 1%. PPV…", "Резко упадёт: ложноположительных станет больше, чем истинных", ["Не изменится: это свойство теста", "Вырастет", "Станет 100%"],
    "Se и Sp не меняются, а PPV зависит от распространённости.", sd())],
widget="dx")

lesson(P5, "Сколько животных проверить, чтобы найти болезнь", "Выборка для подтверждения свободы стада",
"""<p>Вопрос мониторинга: сколько свиней обследовать, чтобы с уверенностью 95% найти хотя бы одну положительную, если болезнь есть с распространённостью не ниже p?</p>
<p>Большое стадо, идеальный тест: n = ln(1 − 0,95) / ln(1 − p). При p = 10% → n = 29 (знаменитые «30 свиней»). При p = 5% → 59. При p = 1% → 299.</p>
<p>Если тест несовершенный (Se &lt; 1), используют p × Se вместо p. Для маленького стада число меньше (поправка на конечную совокупность).</p>
<p>Отрицательный результат при n = 29 значит не «болезни нет», а «если она есть, то распространённость скорее всего ниже 10%».</p>
<p>Ещё важно <b>как</b> отбирать: болезнь часто сидит кластерами по загонам — брать понемногу из многих загонов, а не 30 свиней из одного.</p>""",
[num("Сколько свиней обследовать, чтобы с 95% уверенностью найти болезнь при распространённости 20% (тест идеальный, стадо большое)?", 13.4,
     "ln(0,05) / ln(0,8) = −2,996 / −0,223 = 13,4 → <b>14</b> свиней.", 0.7),
 mc("Обследовали 30 свиней, все отрицательные. Вывод?", "С уверенностью ~95% распространённость ниже ~10% (при идеальном тесте)", ["Стадо свободно от болезни", "Нужно ещё 30", "Тест не работает"],
    "Отсутствие находок ограничивает распространённость сверху, но не доказывает ноль.", sd())],
widget="detect")

lesson(P5, "Показатели свиноводства и их модели", "ADG, FCR, падёж, отъём, дни до продажи",
"""<table class="pr-t"><tr><th>Показатель</th><th>Единица</th><th>Модель</th><th>На что смотреть</th></tr>
<tr><td>ADG, г/сут</td><td>свинья или загон</td><td><code>lmer(adg ~ trt + (1 | pen))</code></td><td>начальная масса как ковариата</td></tr>
<tr><td>FCR</td><td>загон (корм меряют на загон)</td><td><code>lm</code>/<code>lmer</code> по загонам</td><td>павшие свиньи искажают FCR — корм, съеденный павшими</td></tr>
<tr><td>Падёж</td><td>загон</td><td><code>glmer(cbind(dead, alive) ~ trt + (1 | room))</code></td><td>сверхдисперсия: вспышки в отдельных загонах</td></tr>
<tr><td>Отъём на свиноматку</td><td>свиноматка</td><td>Пуассон или lm, повторные опоросы → <code>(1 | sow)</code></td><td>номер опороса</td></tr>
<tr><td>Случаи болезни</td><td>загон</td><td>Пуассон + <code>offset(log(свинодни))</code></td><td>разное время под риском</td></tr>
<tr><td>Дни до продажи</td><td>свинья</td><td>выживаемость (Каплан — Мейер, Кокс)</td><td>цензура: проданные раньше / павшие</td></tr></table>
<p>Отношения вроде FCR и «привес на корм» неудобны: шум числителя и знаменателя складывается. Иногда честнее моделировать потребление корма с привесом как ковариатой.</p>
<p>Производственные данные (не опыт) отвечают на «что связано», но не «что вызывает»: сезон, партия, здоровье стада смешаны со всем.</p>""",
[mc("Корм взвешивают на загон, свиней — по отдельности. Единица для FCR?", "Загон", ["Свинья", "Кормушка", "Рацион"], "FCR считается только там, где известен корм — на загон.", sd()),
 mc("Падёж по 40 загонам: в 3 загонах вспышка (30%), в остальных 2–4%. Чем это опасно для glm binomial?", "Сверхдисперсия: SE занижены — нужен (1 | pen) или quasibinomial",
    ["Ничем", "Нужно удалить три загона", "Надо перейти на lm"], "Разброс между загонами больше, чем допускает биномиальная модель.", sd())])

lesson(P5, "Время до события", "Выживаемость, цензура, Каплан — Мейер",
"""<p>«Сколько дней до продажи», «когда выбраковали свиноматку», «через сколько дней после отъёма пришла в охоту» — это <b>время до события</b>. Особенность — <b>цензура</b>: у части животных событие не случилось к концу наблюдения (опыт закончился, свинью перевели). Выбросить их нельзя — это смещение; считать днём события — тоже.</p>
<p><b>Каплан — Мейер</b> — кривая доли «ещё без события» во времени, корректно учитывает цензуру. <b>Лог-ранговый тест</b> сравнивает кривые групп. <b>Модель Кокса</b> — регрессия: hazard ratio (HR) = во сколько раз выше мгновенный риск события.</p>
<pre class="pr-code">library(survival)
fit <- survfit(Surv(days, event) ~ trt, data = sows)   # event: 1 = событие, 0 = цензура
plot(fit); survdiff(Surv(days, event) ~ trt, data = sows)
m <- coxph(Surv(days, event) ~ trt + parity, data = sows); summary(m)   # exp(coef) = HR</pre>
<p>Предпосылка Кокса — пропорциональность рисков (HR постоянный во времени): <code>cox.zph(m)</code>.</p>""",
[mc("Опыт закончился на 180-й день, 12 свиней ещё не проданы. Как учесть?", "Цензура: event = 0, days = 180", ["Удалить их", "Поставить days = 180 и event = 1", "Поставить days = NA"],
    "Мы знаем только, что событие позже 180 — это и есть цензурированное наблюдение.", sd()),
 mc("Кокс: HR для новой схемы = 0,6 (выбраковка). Что значит?", "Мгновенный риск выбраковки на новой схеме на 40% ниже", ["Выбраковано 60% свиноматок", "Срок жизни вырос на 60%", "Риск выше в 1,6 раза"],
    "HR — отношение рисков в каждый момент времени.", sd())])

lesson(P5, "Как писать результат и проверять себя", "Отчёт, воспроизводимость, чек-лист",
"""<p><b>Формула одной фразы результата:</b> что сравнили, оценка эффекта в единицах, 95% ДИ, метод, p, n единиц.<br>
<i>«Привес на рационе B был выше на 48 г/сут (95% ДИ 12–84; lmer с загоном как случайным эффектом, p = 0,011; 8 загонов на рацион).»</i></p>
<p><b>Воспроизводимость:</b></p><ul><li>сырые данные не правят руками в Excel — все исправления в скрипте с комментарием «почему»;</li>
<li>один скрипт от <code>read.csv</code> до таблиц и графиков; <code>set.seed</code> для жребия и симуляций;</li>
<li>сохраняй <code>sessionInfo()</code> — версии пакетов.</li></ul>
<p><b>Чек-лист перед отправкой:</b></p><ol><li>Единица анализа = единица эксперимента?</li><li>Диапазоны и пропуски проверены (<code>summary</code>, <code>table</code>)?</li>
<li>Модель повторяет дизайн (блоки, загоны, повторные измерения)?</li><li>Графики остатков посмотрены?</li><li>Эффект в понятных единицах, с ДИ, а не только p?</li>
<li>Выводы не шире данных (ферма, возраст, генетика)?</li><li>Множественные сравнения учтены?</li></ol>""",
[multi("Что должно быть в фразе результата?", [("Оценка эффекта в единицах измерения", True), ("95% ДИ", True), ("Метод и p", True), ("Число единиц эксперимента", True),
                                                ("Слово «доказано»", False)], "«Доказано» статистика не говорит; она даёт оценку и неопределённость.", sd()),
 mc("Нашёл опечатку в данных (масса 15,6 вместо 1,56). Как правильно?", "Исправить в скрипте строкой кода с комментарием и ссылкой на журнал",
    ["Исправить в Excel и сохранить поверх", "Удалить строку", "Оставить, раз так записано"], "Правка в коде видна, проверяема и повторяема.", sd())])


